}
MillHopperVibratorMaker.ironStock=16; MillHopperVibratorMaker.bronzeStock=12; MillHopperVibratorMaker.woodStock=12; MillHopperVibratorMaker.leatherStock=8; MillHopperVibratorMaker.silverStock=8; MillHopperVibratorMaker.goldStock=6; MillHopperVibratorMaker.jewelStock=4; MillHopperVibratorMaker.pearlStock=4
MillHopperVibratorMaker.productStock = {}; MillHopperVibratorMaker.buildings = {}; MillHopperVibratorMaker.maker = nil; MillHopperVibratorMaker.activeMaking = {}; MillHopperVibratorMaker.totalProducts = 0; MillHopperVibratorMaker.dayTimer = 0
function MillHopperVibratorMaker.init() MillHopperVibratorMaker.ironStock=16; MillHopperVibratorMaker.bronzeStock=12; MillHopperVibratorMaker.woodStock=12; MillHopperVibratorMaker.leatherStock=8; MillHopperVibratorMaker.silverStock=8; MillHopperVibratorMaker.goldStock=6; MillHopperVibratorMaker.jewelStock=4; MillHopperVibratorMaker.pearlStock=4; MillHopperVibratorMaker.productStock={}; MillHopperVibratorMaker.buildings={}; MillHopperVibratorMaker.maker=nil; MillHopperVibratorMaker.activeMaking={}; MillHopperVibratorMaker.totalProducts=0; MillHopperVibratorMaker.dayTimer=0; print("[MillHopperVibratorMaker] Royal Mill Hopper Vibrator Maker System initialized (6 products, 4 buildings)") end
function MillHopperVibratorMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillHopperVibratorMaker.maker={name=n or ("Treskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Treskar najet: %s (spretnost: %d)",MillHopperVibratorMaker.maker.name,s),"success") end; return true end
function MillHopperVibratorMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillHopperVibratorMaker.build(id) local ok,e=MillHopperVibratorMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillHopperVibratorMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillHopperVibratorMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillHopperVibratorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillHopperVibratorMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillHopperVibratorMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillHopperVibratorMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillHopperVibratorMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillHopperVibratorMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillHopperVibratorMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillHopperVibratorMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillHopperVibratorMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillHopperVibratorMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillHopperVibratorMaker.buildings==0 then return false,"Potrebna treskalna delavnica" end; if not MillHopperVibratorMaker.maker then return false,"Potreben treskar" end; return true end
function MillHopperVibratorMaker.make(pt,qty) qty=qty or 1; local ok,e=MillHopperVibratorMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillHopperVibratorMaker.ironStock=MillHopperVibratorMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillHopperVibratorMaker.bronzeStock=MillHopperVibratorMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillHopperVibratorMaker.woodStock=MillHopperVibratorMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillHopperVibratorMaker.leatherStock=MillHopperVibratorMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillHopperVibratorMaker.silverStock=MillHopperVibratorMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillHopperVibratorMaker.goldStock=MillHopperVibratorMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillHopperVibratorMaker.jewelStock=MillHopperVibratorMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillHopperVibratorMaker.pearlStock=MillHopperVibratorMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillHopperVibratorMaker.maker then t=math.max(1,t-math.floor(MillHopperVibratorMaker.maker.skill/13)) end; table.insert(MillHopperVibratorMaker.activeMaking,{id="millhoppervibrator_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillHopperVibratorMaker.completeMaking(m) local q=1.0+(MillHopperVibratorMaker.getQualityBonus()/100); if MillHopperVibratorMaker.maker then q=q+(MillHopperVibratorMaker.maker.skill/140) end; q=math.min(2.5,q); MillHopperVibratorMaker.productStock[m.productType]=(MillHopperVibratorMaker.productStock[m.productType] or 0)+m.quantity; MillHopperVibratorMaker.totalProducts=MillHopperVibratorMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillHopperVibratorMaker.maker then MillHopperVibratorMaker.maker.itemsMade=MillHopperVibratorMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillHopperVibratorMaker.maker.skill=math.min(100,MillHopperVibratorMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vibrator izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millhoppervibrator.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillHopperVibratorMaker.update(dt) if not _G.state then return end; MillHopperVibratorMaker.dayTimer=MillHopperVibratorMaker.dayTimer+dt; if MillHopperVibratorMaker.dayTimer>=30 then MillHopperVibratorMaker.dayTimer=0; for i=#MillHopperVibratorMaker.activeMaking,1,-1 do local m=MillHopperVibratorMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillHopperVibratorMaker.completeMaking(m); table.remove(MillHopperVibratorMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillHopperVibratorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillHopperVibratorMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillHopperVibratorMaker.getStats() return {ironStock=MillHopperVibratorMaker.ironStock,bronzeStock=MillHopperVibratorMaker.bronzeStock,woodStock=MillHopperVibratorMaker.woodStock,leatherStock=MillHopperVibratorMaker.leatherStock,silverStock=MillHopperVibratorMaker.silverStock,goldStock=MillHopperVibratorMaker.goldStock,jewelStock=MillHopperVibratorMaker.jewelStock,pearlStock=MillHopperVibratorMaker.pearlStock,productStock=MillHopperVibratorMaker.productStock,numBuildings=#MillHopperVibratorMaker.buildings,hasMaker=MillHopperVibratorMaker.maker~=nil,makerName=MillHopperVibratorMaker.maker and MillHopperVibratorMaker.maker.name or "—",makerSkill=MillHopperVibratorMaker.maker and MillHopperVibratorMaker.maker.skill or 0,activeMaking=#MillHopperVibratorMaker.activeMaking,totalProducts=MillHopperVibratorMaker.totalProducts} end
